local language = vim.treesitter.language.get_lang(vim.bo.filetype); assert(vim.bo.filetype == "tf" or vim.bo.filetype == "terraform", "unexpected filetype: " .. vim.bo.filetype); assert(language == "terraform", "unexpected language: " .. tostring(language)); local parser_ok, parser_error; local ready = vim.wait(60000, function() parser_ok, parser_error = pcall(vim.treesitter.get_parser, 0, language); return parser_ok end, 100); assert(ready, "Tree-sitter parser did not finish auto-installing: " .. tostring(parser_error)); print("Neovim developer smoke: OK")
